}

/* Custom Scrollbar - Now applied to the whole document */
html::-webkit-scrollbar { width: 8px; }
html::-webkit-scrollbar-track { background: #0f172a; }
html::-webkit-scrollbar-thumb { background-color: #0891b2; border-radius: 20px; border: 2px solid #0f172a; }

/* Custom Scrollbar for mobile-scrollable elements */
.mobile-scroll-x {
