}
.mobile-scroll-x:hover::-webkit-scrollbar-thumb {
  background-color: #0891b2; /* Solid cyan on hover */
}


/* Text Glitch Effect */
.glitch-text {
  position: relative;
  color: #67e8f9;
  text-shadow: 0 0 5px #0891b2, 0 0 10px #0891b2;
}
.glitch-text::before,
.glitch-text::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  overflow: hidden;
  clip: rect(0, 900px, 0, 0);
}
.glitch-text::before {
  left: 2px;
  text-shadow: -2px 0 #ec4899;
  animation: glitch-anim-1 2s infinite linear alternate-reverse;
}
.glitch-text::after {
  left: -2px;
  text-shadow: -2px 0 #34d399, 2px 2px #ec4899;
  animation: glitch-anim-2 3s infinite linear alternate-reverse;
}

@keyframes glitch-anim-1 {
  0% { clip: rect(42px, 9999px, 44px, 0); }
  5% { clip: rect(12px, 9999px, 60px, 0); }
  100% { clip: rect(90px, 9999px, 98px, 0); }
}
@keyframes glitch-anim-2 {
