const path = require('path');
const fs = require('fs');

const DB_PATH = path.join(__dirname, 'database.sqlite');
let _db = null;

/**
 * SQL KERNEL CONNECTOR
 * Handles native binary mismatches (self-register errors) 
 * and provides clear recovery instructions for SSH.
 */
const connect = () => {
    if (_db) return _db;

    try {
        // Attempt to load the native SQL driver
        const Database = require('better-sqlite3');

        const dir = path.dirname(DB_PATH);
        if (!fs.existsSync(dir)) {
            fs.mkdirSync(dir, { recursive: true });
        }

        _db = new Database(DB_PATH, { timeout: 10000 });
        _db.pragma('journal_mode = WAL');
        _db.pragma('foreign_keys = ON');

        // Verify connectivity
        _db.prepare("SELECT 1").get();
        console.log('[DB] SQL Engine Online.');
        return _db;
    } catch (e) {
        console.error("!!! DATABASE KERNEL PANIC !!!");
        console.error(e.message);

        let msg = "Database Offline";
        let fix = "Run the Nuclear Remake command.";

        // Identify binary mismatch / compilation errors
        if (e.message.includes('self-register') || 
            e.message.includes('NODE_MODULE_VERSION') || 
            e.code === 'ERR_DLOPEN_FAILED') {
            msg = "Binary Mismatch Error (SQL Driver Needs Reinstall)";
            fix = "SSH Command: rm -rf node_modules && npm install";
        }

        const err = new Error(msg);
        err.raw = e.message;
        err.fix = fix;
        // The exact command the user needs to paste into their SSH terminal
        err.terminal = "cd /var/www/html/A-babaexch/backend && pm2 stop ababa-backend || true && rm -rf node_modules package-lock.json database.sqlite* && npm install && npm run db:setup && pm2 start server.js --name ababa-backend";
        throw err;
    }
};

const getDB = () => {
    if (!_db) return connect();
    return _db;
};

const safeParse = (str) => {
    try { return str ? JSON.parse(str) : null; } 
    catch (e) { return null; }
};

const getAllFromTable = (table) => {
    const db = getDB();
    try {
        const items = db.prepare(`SELECT * FROM ${table}`).all();
        return items.map(item => {
            if (item.prizeRates) item.prizeRates = safeParse(item.prizeRates);
            if (item.betLimits) item.betLimits = safeParse(item.betLimits);
            if (item.numbers) item.numbers = safeParse(item.numbers);
            return item;
        });
    } catch (err) {
        throw err;
    }
};

module.exports = {
    connect,
    verifySchema: () => {
        try {
            const db = getDB();
            const res = db.prepare(`SELECT name FROM sqlite_master WHERE type='table' AND name='admins'`).get();
            return !!res;
        } catch (e) {
            return false;
        }
    },
    getAllFromTable,
    findAccountForLogin: (loginId) => {
        const db = getDB();
        const roles = [{ table: 'users', role: 'USER' }, { table: 'dealers', role: 'DEALER' }, { table: 'admins', role: 'ADMIN' }];
        for (const r of roles) {
            const acc = db.prepare(`SELECT * FROM ${r.table} WHERE id = ?`).get(loginId);
            if (acc) return { account: acc, role: r.role };
        }
        return { account: null, role: null };
    },
    findAccountById: (id, table) => {
        const db = getDB();
        const acc = db.prepare(`SELECT * FROM ${table} WHERE id = ?`).get(id);
        if (!acc) return null;
        acc.prizeRates = safeParse(acc.prizeRates);
        acc.ledger = db.prepare('SELECT * FROM ledgers WHERE accountId = ? ORDER BY timestamp DESC LIMIT 50').all(id);
        return acc;
    },
    runInTransaction: (fn) => getDB().transaction(fn)()
};

require('dotenv').config();
const express = require('express');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const authMiddleware = require('./authMiddleware');
const database = require('./database');
const { GoogleGenAI } = require("@google/genai");

const app = express();
app.use(cors());
app.use(express.json());

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

let dbReady = false;
let dbErrorData = null;

const checkDBStatus = () => {
    try {
        database.connect();
        if (database.verifySchema()) {
            dbReady = true;
            dbErrorData = null;
            return true;
        } else {
            dbReady = false;
            dbErrorData = { 
                error: "Schema Missing", 
                terminal: "npm run db:setup",
                fix: "Your database file is missing or empty. Run the setup script."
            };
        }
    } catch (e) {
        dbReady = false;
        dbErrorData = { 
            error: e.message, 
            raw: e.raw || e.toString(), 
            terminal: e.terminal || "npm install",
            fix: e.fix || "A critical driver error has occurred."
        };
    }
    return false;
};

// Initial Health Check
checkDBStatus();

// Global health check middleware
app.use('/api', (req, res, next) => {
    if (!dbReady && !['/status', '/games'].includes(req.path)) {
        checkDBStatus();
    }
    next();
});

app.get('/api/games', (req, res) => {
    // Every time games are requested, if we are in an error state, retry once.
    if (!dbReady) {
        checkDBStatus();
    }

    if (!dbReady) {
        return res.status(503).json(dbErrorData);
    }

    try {
        const games = database.getAllFromTable('games');
        res.json(games);
    } catch (e) {
        res.status(500).json({ error: "Query failed", details: e.message });
    }
});

app.post('/api/auth/login', (req, res) => {
    if (!dbReady) return res.status(503).json({ message: "Database offline. Run remake command." });
    const { loginId, password } = req.body;
    try {
        const { account, role } = database.findAccountForLogin(loginId);
        if (account && account.password === password) {
            const token = jwt.sign({ id: account.id, role }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
            const fullAccount = database.findAccountById(account.id, role.toLowerCase() + 's');
            return res.json({ token, role, account: fullAccount });
        }
        res.status(401).json({ message: "Invalid credentials" });
    } catch (e) {
        res.status(500).json({ message: "Login failed.", error: e.message });
    }
});

app.get('/api/admin/data', authMiddleware, (req, res) => {
    if (req.user.role !== 'ADMIN') return res.sendStatus(403);
    try {
        res.json({
            dealers: database.getAllFromTable('dealers'),
            users: database.getAllFromTable('users'),
            games: database.getAllFromTable('games'),
            bets: database.getAllFromTable('bets')
        });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

