const { Pool } = require('pg');
require('dotenv').config();

const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgresql://ababauser:ababa123@localhost:5432/ababa',
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

/**
 * POSTGRES KERNEL
 * Replaces the problematic SQLite driver with a robust, async pool.
 */
const query = async (text, params) => {
  try {
    const res = await pool.query(text, params);
    return res;
  } catch (e) {
    console.error('[DB ERROR]', e.message);
    const err = new Error("Database Logic Error");
    err.terminal = "Check PostgreSQL Service: sudo systemctl status postgresql";
    err.fix = "Ensure database 'ababa' and user 'ababauser' exist.";
    throw err;
  }
};

const safeParse = (str) => {
  try { return str ? (typeof str === 'string' ? JSON.parse(str) : str) : null; } 
  catch (e) { return null; }
};

module.exports = {
  pool,
  verifySchema: async () => {
    try {
      const res = await pool.query("SELECT to_regclass('public.admins') as exists");
      return !!res.rows[0].exists;
    } catch (e) {
      return false;
    }
  },

  getAllFromTable: async (table) => {
    const res = await pool.query(`SELECT * FROM ${table}`);
    return res.rows.map(item => {
      if (item.prizerates) item.prizeRates = safeParse(item.prizerates);
      if (item.betlimits) item.betLimits = safeParse(item.betlimits);
      if (item.numbers) item.numbers = safeParse(item.numbers);
      return item;
    });
  },

  findAccountForLogin: async (loginId) => {
    const roles = [
      { table: 'users', role: 'USER' },
      { table: 'dealers', role: 'DEALER' },
      { table: 'admins', role: 'ADMIN' }
    ];
    for (const r of roles) {
      const res = await pool.query(`SELECT * FROM ${r.table} WHERE id = $1`, [loginId]);
      if (res.rows[0]) return { account: res.rows[0], role: r.role };
    }
    return { account: null, role: null };
  },

  findAccountById: async (id, table) => {
    const res = await pool.query(`SELECT * FROM ${table} WHERE id = $1`, [id]);
    const acc = res.rows[0];
    if (!acc) return null;

    acc.prizeRates = safeParse(acc.prizerates || acc.prizeRates);
    const ledgerRes = await pool.query('SELECT * FROM ledgers WHERE accountId = $1 ORDER BY timestamp DESC LIMIT 50', [id]);
    acc.ledger = ledgerRes.rows;
    return acc;
  }
};

require('dotenv').config();
const express = require('express');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const authMiddleware = require('./authMiddleware');
const database = require('./database');

const app = express();
app.use(cors());
app.use(express.json());

let dbReady = false;
let dbErrorData = null;

const checkDBStatus = async () => {
    try {
        const isReady = await database.verifySchema();
        if (isReady) {
            dbReady = true;
            dbErrorData = null;
            return true;
        } else {
            dbReady = false;
            dbErrorData = { 
                error: "Schema Missing", 
                terminal: "npm run db:setup",
                fix: "PostgreSQL is connected but tables are missing. Run the setup script."
            };
        }
    } catch (e) {
        dbReady = false;
        dbErrorData = { 
            error: "PostgreSQL Connection Failed", 
            raw: e.message, 
            terminal: "sudo systemctl restart postgresql",
            fix: "The backend cannot reach your Postgres server. Check credentials in .env"
        };
    }
    return false;
};

// Periodic Check
setInterval(checkDBStatus, 10000);
checkDBStatus();

app.use('/api', async (req, res, next) => {
    if (!dbReady && !['/status', '/games'].includes(req.path)) {
        await checkDBStatus();
    }
    next();
});

app.get('/api/games', async (req, res) => {
    if (!dbReady) await checkDBStatus();
    if (!dbReady) return res.status(503).json(dbErrorData);

    try {
        const games = await database.getAllFromTable('games');
        res.json(games);
    } catch (e) {
        res.status(500).json({ error: "Postgres Query Failed", details: e.message });
    }
});

app.post('/api/auth/login', async (req, res) => {
    if (!dbReady) return res.status(503).json({ message: "Database offline. Check Postgres." });
    const { loginId, password } = req.body;
    try {
        const { account, role } = await database.findAccountForLogin(loginId);
        if (account && account.password === password) {
            const token = jwt.sign({ id: account.id, role }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
            const fullAccount = await database.findAccountById(account.id, role.toLowerCase() + 's');
            return res.json({ token, role, account: fullAccount });
        }
        res.status(401).json({ message: "Invalid credentials" });
    } catch (e) {
        res.status(500).json({ message: "Login failed.", error: e.message });
    }
});

app.get('/api/admin/data', authMiddleware, async (req, res) => {
    if (req.user.role !== 'ADMIN') return res.sendStatus(403);
    try {
        res.json({
            dealers: await database.getAllFromTable('dealers'),
            users: await database.getAllFromTable('users'),
            games: await database.getAllFromTable('games'),
            bets: await database.getAllFromTable('bets')
        });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

app.get('/api/auth/verify', authMiddleware, async (req, res) => {
    try {
        const table = req.user.role.toLowerCase() + 's';
        const account = await database.findAccountById(req.user.id, table);
        if (!account) return res.status(404).json({ message: 'Account not found' });
        res.json({ account, role: req.user.role });
    } catch (e) {
        res.status(500).json({ message: e.message });
    }
});

