app.get('/api/admin/summary', authMiddleware, async (req, res) => {
    if (req.user.role !== 'ADMIN') return res.sendStatus(403);
    try {
        const games = await database.getAllFromTable('games');
        const bets = await database.query('SELECT * FROM bets');

        let totalStake = 0;
        const gameSummaries = games.map(game => {
            const gameBets = bets.filter(b => b.gameId === game.id);
            const stake = gameBets.reduce((s, b) => s + parseFloat(b.totalAmount), 0);
            totalStake += stake;
            return {
                gameName: game.name,
                winningNumber: game.winningNumber || '-',
                totalStake: stake,
                totalPayouts: 0, 
                totalDealerProfit: 0,
                totalCommissions: 0,
                netProfit: stake
            };
        });

        res.json({ 
            games: gameSummaries, 
            totals: { 
                totalStake, 
                totalPayouts: 0, 
                totalDealerProfit: 0,
                totalCommissions: 0,
                netProfit: totalStake 
            },
            totalBets: bets.length
        });
    } catch (e) { res.status(500).send(); }
});

// New Endpoint: Market Exposure (Which number is played with how much money)
app.get('/api/admin/games/:id/exposure', authMiddleware, async (req, res) => {
    if (req.user.role !== 'ADMIN') return res.sendStatus(403);
    try {
        const bets = await database.query('SELECT * FROM bets WHERE gameid = ?', [req.params.id]);
        const exposure = {};

        // Initialize 00-99
        for(let i=0; i<100; i++) exposure[i.toString().padStart(2, '0')] = 0;

        bets.forEach(bet => {
            const nums = JSON.parse(bet.numbers);
            nums.forEach(n => {
                // Map 1-digit to 2-digit range if needed, or handle separately
                // For simplicity, we track exactly as played
                exposure[n] = (exposure[n] || 0) + parseFloat(bet.amountpernumber);
            });
        });

        res.json({ exposure });
    } catch (e) { res.status(500).send(); }
});

app.post('/api/admin/games/:id/declare-winner', authMiddleware, async (req, res) => {
