                              <p className="text-[10px] text-slate-500 uppercase tracking-widest mb-2">Market Result</p>
                              <p className={`text-4xl font-bold font-mono tracking-tighter ${game.winningNumber ? 'text-emerald-400' : 'text-slate-600'}`}>
                                  {game.winningNumber || '--'}
                              </p>
                          </div>
                      </div>
                      <button 
                        onClick={() => { 
                            setGameWinnerModal(game); 
                            setWinningNumberInput(game.winningNumber || ''); 
                            setIsUpdatingWinner(!!game.winningNumber);
                        }} 
                        className={`w-full py-3 rounded font-bold uppercase text-xs tracking-widest transition-all ${game.winningNumber ? 'bg-amber-600 hover:bg-amber-500' : 'bg-red-600 hover:bg-red-500'} text-white`}
                      >
                          {game.winningNumber ? 'Edit Result' : 'Declare Result'}
