      {/* WINNER DECLARATION MODAL */}
      <Modal isOpen={!!gameWinnerModal} onClose={() => setGameWinnerModal(null)} title={isUpdatingWinner ? `EDIT WINNER: ${gameWinnerModal?.name}` : `DECLARE WINNER: ${gameWinnerModal?.name}`} themeColor={isUpdatingWinner ? 'amber' : 'red'}>
          <div className="space-y-6">
              <p className="text-slate-400 text-center">
                  {isUpdatingWinner ? 'Carefully enter the corrected winning number. This will recalculate exposure and potential winnings.' : 'Submit official result for the draw. This action is critical and will update exposure calculations.'}
              </p>
              <div className="flex flex-col items-center">
                  <label className="text-[10px] font-bold text-slate-500 uppercase mb-2">Final Winning Number</label>
                  <input 
                    maxLength={2} 
                    type="text" 
                    autoFocus
                    value={winningNumberInput} 
                    onChange={e => setWinningNumberInput(e.target.value.replace(/\D/g, ''))} 
                    className={`w-32 bg-slate-950 p-4 text-6xl text-center font-bold ${isUpdatingWinner ? 'text-amber-500 border-amber-500/50 shadow-[0_0_20px_rgba(245,158,11,0.2)]' : 'text-red-500 border-red-500/50 shadow-[0_0_20px_rgba(239,68,68,0.2)]'} border-2 rounded focus:outline-none`} 
                  />
              </div>
              <button 
                onClick={handleWinnerSubmit} 
                className={`w-full py-4 ${isUpdatingWinner ? 'bg-amber-600 hover:bg-amber-500' : 'bg-red-600 hover:bg-red-500'} text-white rounded font-bold shadow-lg`}
              >
                  {isUpdatingWinner ? 'CONFIRM CORRECTION' : 'CONFIRM & BROADCAST'}
              </button>
          </div>
      </Modal>

    </div>
  );
};

