  const [viewingLedgerFor, setViewingLedgerFor] = useState<User | Dealer | null>(null);
  const { fetchWithAuth } = useAuth();

  const fetchSummary = async () => {
    try {
      const response = await fetchWithAuth('/api/admin/summary');
