const WalletTransactionForm: React.FC<{
    account: Dealer | User;
    type: 'Top-Up' | 'Withdrawal';
    onTransaction: (id: string, amount: number) => Promise<void>;
    onCancel: () => void;
}> = ({ account, type, onTransaction, onCancel }) => {
    const [amount, setAmount] = useState<number | ''>('');
    const [error, setError] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const themeColor = type === 'Top-Up' ? 'emerald' : 'amber';

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!amount || amount <= 0) {
            setError("Please enter a valid positive amount.");
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            await onTransaction(account.id, Number(amount));
            onCancel();
        } catch (err: any) {
            setError(err.message || 'Transaction failed');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="bg-slate-800/50 p-4 rounded border border-slate-700 text-center">
                <p className="text-slate-400 text-xs uppercase mb-1">Target Account</p>
                <p className="text-white font-bold text-lg">{account.name} ({account.id})</p>
                <p className="text-cyan-400 font-mono text-sm mt-1">Current Balance: PKR {account.wallet.toLocaleString()}</p>
            </div>
            <div>
                <label className="block text-sm font-medium text-slate-300 mb-2 uppercase tracking-wider">Amount (PKR)</label>
                <input
                    type="number"
                    value={amount}
                    onChange={e => setAmount(e.target.value === '' ? '' : parseFloat(e.target.value))}
                    className="w-full bg-slate-950 p-4 text-3xl text-center font-bold text-white border-2 border-slate-700 rounded focus:border-cyan-500 outline-none transition-colors"
                    placeholder="0.00"
                    autoFocus
                />
            </div>
            {error && <p className="text-red-400 text-sm bg-red-400/10 p-3 rounded border border-red-400/20">{error}</p>}
            <div className="flex gap-3">
                <button type="button" onClick={onCancel} className="flex-1 py-3 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded transition-colors">CANCEL</button>
                <button type="submit" disabled={isLoading} className={`flex-1 py-3 ${type === 'Top-Up' ? 'bg-emerald-600 hover:bg-emerald-500' : 'bg-amber-600 hover:bg-amber-500'} text-white font-bold rounded transition-colors disabled:opacity-50`}>
                    {isLoading ? 'PROCESSING...' : `CONFIRM ${type.toUpperCase()}`}
                </button>
            </div>
        </form>
    );
};

const LiveMarketView: React.FC<{ games: Game[] }> = ({ games }) => {
    const { fetchWithAuth } = useAuth();
    const [selectedGameId, setSelectedGameId] = useState(games[0]?.id || '');
    const [exposure, setExposure] = useState<Record<string, number>>({});
    const [isLoading, setIsLoading] = useState(false);

    const fetchExposure = async () => {
        if (!selectedGameId) return;
        setIsLoading(true);
        try {
            const res = await fetchWithAuth(`/api/admin/games/${selectedGameId}/exposure`);
            const data = await res.json();
            setExposure(data.exposure || {});
        } catch (e) { console.error(e); } finally { setIsLoading(false); }
    };

    useEffect(() => { fetchExposure(); }, [selectedGameId]);
    const maxStake = Math.max(...Object.values(exposure), 1);

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <h3 className="text-xl font-bold text-white flex items-center gap-2">{Icons.sparkles} Live Market Exposure</h3>
                <div className="flex gap-2">
                    <select value={selectedGameId} onChange={(e) => setSelectedGameId(e.target.value)} className="bg-slate-800 border border-slate-700 text-white p-2 rounded focus:ring-2 focus:ring-cyan-500">
                        {games.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                    </select>
                    <button onClick={fetchExposure} className="p-2 bg-slate-700 rounded hover:bg-slate-600 transition-colors">Refresh</button>
                </div>
            </div>
            <div className="grid grid-cols-5 sm:grid-cols-10 gap-2">
                {Object.entries(exposure).sort(([a], [b]) => a.localeCompare(b)).map(([num, stake]) => {
                    const intensity = (stake / maxStake) * 100;
                    return (
                        <div key={num} className="group relative flex flex-col items-center justify-center p-2 rounded border border-slate-700 transition-all hover:scale-110 z-10 hover:z-20" style={{ backgroundColor: stake > 0 ? `rgba(6, 182, 212, ${Math.max(0.1, intensity/100)})` : 'transparent' }}>
                            <span className="text-lg font-bold text-white">{num}</span>
                            <span className="text-[10px] font-mono text-cyan-200">Rs.{stake.toFixed(0)}</span>
                            <div className="absolute bottom-full mb-2 hidden group-hover:block bg-slate-950 p-2 rounded shadow-xl text-xs whitespace-nowrap border border-cyan-500">
                                <p>Number: <span className="font-bold">{num}</span></p>
                                <p>Total Played: <span className="font-bold text-cyan-400">Rs.{stake.toLocaleString()}</span></p>
                                <p>Potential Loss: <span className="font-bold text-red-400">Rs.{(stake * 900).toLocaleString()}</span></p>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

const WinnersReportView: React.FC<{ bets: Bet[], games: Game[], users: User[] }> = ({ bets, games, users }) => {
    const winners = useMemo(() => {
        return bets.filter(bet => {
            const game = games.find(g => g.id === bet.gameId);
            if (!game || !game.winningNumber) return false;
            return bet.numbers.includes(game.winningNumber);
        }).map(bet => {
            const game = games.find(g => g.id === bet.gameId)!;
            const user = users.find(u => u.id === bet.userId);
            const winAmount = (bet.amountPerNumber || 0) * 900;
            return { id: bet.id, userName: user?.name || bet.userId, gameName: game.name, winningNumber: game.winningNumber, stake: bet.amountPerNumber, prize: winAmount, timestamp: bet.timestamp };
        });
    }, [bets, games, users]);

    return (
        <div className="space-y-4">
            <h3 className="text-xl font-bold text-white">Winners Detailed Report</h3>
            <div className="bg-slate-800/50 rounded-lg overflow-hidden border border-slate-700">
                <div className="max-h-[500px] overflow-y-auto">
                    <table className="w-full text-left">
                        <thead className="bg-slate-900 sticky top-0">
                            <tr className="text-xs text-slate-400 uppercase">
                                <th className="p-4">Time</th>
                                <th className="p-4">User</th>
                                <th className="p-4">Game</th>
                                <th className="p-4">Number</th>
                                <th className="p-4 text-right">Stake</th>
                                <th className="p-4 text-right">Prize Won</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800">
                            {winners.map(w => (
                                <tr key={w.id} className="hover:bg-emerald-500/10">
                                    <td className="p-4 text-xs text-slate-500">{new Date(w.timestamp).toLocaleString()}</td>
                                    <td className="p-4 font-bold text-white">{w.userName}</td>
                                    <td className="p-4 text-slate-300">{w.gameName}</td>
                                    <td className="p-4 font-mono text-emerald-400 font-bold">{w.winningNumber}</td>
                                    <td className="p-4 text-right font-mono">Rs.{parseFloat(w.stake as any).toFixed(0)}</td>
                                    <td className="p-4 text-right font-mono text-emerald-400 font-bold">Rs.{w.prize.toLocaleString()}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

