                  onTransaction={transactionModal.type === 'Top-Up' ? topUpDealerWallet : withdrawFromDealerWallet}
                  onCancel={() => setTransactionModal(null)}
              />
          )}
      </Modal>

      {/* WINNER DECLARATION MODAL */}
      <Modal isOpen={!!gameWinnerModal} onClose={() => setGameWinnerModal(null)} title={isUpdatingWinner ? `EDIT WINNER: ${gameWinnerModal?.name}` : `DECLARE WINNER: ${gameWinnerModal?.name}`} themeColor={isUpdatingWinner ? 'amber' : 'red'}>
