              <p className="text-slate-400 text-center">{isUpdatingWinner ? 'Carefully enter the corrected winning number.' : 'Submit official result for the draw.'}</p>
              <div className="flex flex-col items-center">
                  <label className="text-[10px] font-bold text-slate-500 uppercase mb-2">Final Winning Number</label>
                  <input maxLength={2} type="text" autoFocus value={winningNumberInput} onChange={e => setWinningNumberInput(e.target.value.replace(/\D/g, ''))} className={`w-32 bg-slate-950 p-4 text-6xl text-center font-bold ${isUpdatingWinner ? 'text-amber-500 border-amber-500/50' : 'text-red-500 border-red-500/50'} border-2 rounded focus:outline-none`} />
              </div>
              <button onClick={handleWinnerSubmit} className={`w-full py-4 ${isUpdatingWinner ? 'bg-amber-600 hover:bg-amber-500' : 'bg-red-600 hover:bg-red-500'} text-white rounded font-bold shadow-lg`}>{isUpdatingWinner ? 'CONFIRM CORRECTION' : 'CONFIRM & BROADCAST'}</button>
          </div>
      </Modal>
    </div>
  );
};

