        const exposure = {};
        for(let i=0; i<100; i++) exposure[i.toString().padStart(2, '0')] = 0;
        bets.forEach(bet => {
            const nums = JSON.parse(bet.numbers);
            nums.forEach(n => { exposure[n] = (exposure[n] || 0) + parseFloat(bet.amountpernumber); });
