            </div>

            {exposure ? (
                <div className="space-y-12">
                    <ExposureSection title="Two Digit Summary" data={exposure.twoDigit} />
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                        <ExposureSection title="1 Digit Open" data={exposure.oneDigitOpen} cols={5} />
                        <ExposureSection title="1 Digit Close" data={exposure.oneDigitClose} cols={5} />
                    </div>
                </div>
            ) : (
