        if (!res.ok) throw new Error((await res.json()).message);
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const onSaveDealer = useCallback(async (dealerData: Dealer, originalId?: string) => {
        const method = originalId ? 'PUT' : 'POST';
