    const [formData, setFormData] = useState(() => {
        const defaults = {
            id: '', name: '', password: '', area: '', contact: '', commissionRate: 0, 
            prizeRates: { ...dealerPrizeRates }, avatarUrl: '', wallet: '',
            betLimits: { oneDigit: 5000, twoDigit: 2000 }
        };
        if (user) return { ...user, password: '' };
        return defaults;
    });

    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value, type } = e.target;
        if (name.includes('.')) {
            const [parent, child] = name.split('.');
            setFormData(prev => ({ ...prev, [parent]: { ...(prev[parent as keyof typeof prev] as object), [child]: type === 'number' ? parseFloat(value) : value } }));
        } else {
            setFormData(prev => ({ ...prev, [name]: type === 'number' ? (value ? parseFloat(value) : '') : value }));
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const newPassword = user ? password : formData.password!;
        if (newPassword && newPassword !== confirmPassword) return alert("Passwords do not match.");
        setIsLoading(true);
        try {
            const finalData = { ...formData, id: user ? user.id : formData.id, dealerId, password: newPassword || (user?.password || '') };
            await onSave(finalData as any, user?.id, Number(formData.wallet) || 0);
        } finally { setIsLoading(false); }
    };

    const inputClass = "w-full bg-slate-800 p-2.5 rounded-md border border-slate-600 text-white outline-none";

    return (
        <form onSubmit={handleSubmit} className="space-y-4">
             <div className="grid grid-cols-2 gap-4">
                <input type="text" name="id" value={formData.id as string} onChange={handleChange} placeholder="User ID" className={inputClass} required disabled={!!user}/>
                <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Name" className={inputClass} required />
            </div>
            <div className="grid grid-cols-2 gap-4">
                <input type="password" value={user ? password : formData.password!} onChange={user ? (e) => setPassword(e.target.value) : handleChange} placeholder="Password" className={inputClass} required={!user} />
                <input type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Confirm Password" className={inputClass} required={!!(user ? password : formData.password)} />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <input type="text" name="area" value={formData.area} onChange={handleChange} placeholder="Area" className={inputClass} />
                 <input type="text" name="contact" value={formData.contact} onChange={handleChange} placeholder="Contact" className={inputClass} />
            </div>
            {!user && (
                 <div>
                    <label className="block text-xs text-slate-500 uppercase mb-1">Initial Deposit (PKR)</label>
                    <input type="number" name="wallet" value={formData.wallet as string} onChange={handleChange} placeholder="0.00" className={inputClass} />
                </div>
            )}
             <div>
                <label className="block text-xs text-slate-500 uppercase mb-1">Commission Rate (%)</label>
                <input type="number" name="commissionRate" value={formData.commissionRate} onChange={handleChange} placeholder="e.g. 5" className={inputClass} />
            </div>

            <fieldset className="border border-slate-700 p-3 rounded-md">
                <legend className="px-2 text-xs font-bold text-slate-500 uppercase">Prize Rates</legend>
                <div className="grid grid-cols-3 gap-2">
                    <div><label className="text-[10px] text-slate-500">1D OPEN</label><input type="number" name="prizeRates.oneDigitOpen" value={formData.prizeRates.oneDigitOpen} onChange={handleChange} className={inputClass + " text-sm"} /></div>
                    <div><label className="text-[10px] text-slate-500">1D CLOSE</label><input type="number" name="prizeRates.oneDigitClose" value={formData.prizeRates.oneDigitClose} onChange={handleChange} className={inputClass + " text-sm"} /></div>
                    <div><label className="text-[10px] text-slate-500">2D</label><input type="number" name="prizeRates.twoDigit" value={formData.prizeRates.twoDigit} onChange={handleChange} className={inputClass + " text-sm"} /></div>
                </div>
            </fieldset>

            <div className="flex justify-end gap-3 pt-4">
                <button type="button" onClick={onCancel} className="bg-slate-700 px-4 py-2 rounded-md font-bold text-sm uppercase">Cancel</button>
                <button type="submit" disabled={isLoading} className="bg-emerald-600 px-6 py-2 rounded-md font-bold text-sm uppercase shadow-lg shadow-emerald-600/20">{isLoading ? 'Saving...' : 'Save User'}</button>
            </div>
        </form>
    );
};

