export default DealerPanel;

const path = require('path');
const Database = require('better-sqlite3');
const { v4: uuidv4 } = require('uuid');

const DB_PATH = path.join(__dirname, 'database.sqlite');
let db;

const connect = () => {
    db = new Database(DB_PATH);
    db.pragma('journal_mode = WAL');
    db.pragma('foreign_keys = ON');
};

const verifySchema = () => {
    const table = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='admins'").get();
    if (!table) throw new Error("Database not initialized.");
};

const findAccountById = (id, table) => {
    const account = db.prepare(`SELECT * FROM ${table} WHERE id = ?`).get(id);
    if (!account) return null;
    if (table !== 'games') {
        account.ledger = db.prepare('SELECT * FROM ledgers WHERE accountId = ? ORDER BY timestamp ASC').all(id);
    }
    if (account.prizeRates) account.prizeRates = JSON.parse(account.prizeRates);
    if (account.betLimits) account.betLimits = JSON.parse(account.betLimits);
    if ('isRestricted' in account) account.isRestricted = !!account.isRestricted;
    return account;
};

const findAccountForLogin = (loginId) => {
    const lowerId = loginId.toLowerCase();
    for (const t of [{n:'users',r:'USER'},{n:'dealers',r:'DEALER'},{n:'admins',r:'ADMIN'}]) {
        const account = db.prepare(`SELECT * FROM ${t.n} WHERE lower(id) = ?`).get(lowerId);
        if (account) return { account, role: t.r };
    }
    return { account: null, role: null };
};

const getAllFromTable = (table, withLedger = false) => {
    return db.prepare(`SELECT * FROM ${table}`).all().map(acc => {
        if (withLedger) acc.ledger = db.prepare('SELECT * FROM ledgers WHERE accountId = ? ORDER BY timestamp ASC').all(acc.id);
        if (acc.prizeRates) acc.prizeRates = JSON.parse(acc.prizeRates);
        if (acc.betLimits) acc.betLimits = JSON.parse(acc.betLimits);
        if (table === 'bets' && acc.numbers) acc.numbers = JSON.parse(acc.numbers);
        if ('isRestricted' in acc) acc.isRestricted = !!acc.isRestricted;
        return acc;
    });
};

const findUsersByDealerId = (dealerId) => {
    return db.prepare('SELECT * FROM users WHERE dealerId = ?').all(dealerId).map(u => {
        u.prizeRates = JSON.parse(u.prizeRates);
        u.betLimits = u.betLimits ? JSON.parse(u.betLimits) : null;
        u.ledger = db.prepare('SELECT * FROM ledgers WHERE accountId = ? ORDER BY timestamp ASC').all(u.id);
        u.isRestricted = !!u.isRestricted;
        return u;
    });
};

const findBetsByDealerId = (dealerId) => {
    return db.prepare('SELECT * FROM bets WHERE dealerId = ?').all(dealerId).map(b => {
        b.numbers = JSON.parse(b.numbers);
        b.timestamp = new Date(b.timestamp);
        return b;
    });
};

const runInTransaction = (fn) => db.transaction(fn)();

const addLedgerEntry = (accountId, accountType, description, debit, credit) => {
    const table = accountType.toLowerCase() + 's';
    const lastBalance = db.prepare('SELECT balance FROM ledgers WHERE accountId = ? ORDER BY timestamp DESC, ROWID DESC LIMIT 1').get(accountId)?.balance || 0;

    if (debit > 0 && accountType !== 'ADMIN' && lastBalance < debit) {
        throw { status: 400, message: `Insufficient funds for ${accountId}.` };
    }

    const newBalance = lastBalance - debit + credit;
    db.prepare('INSERT INTO ledgers (id, accountId, accountType, timestamp, description, debit, credit, balance) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
      .run(uuidv4(), accountId, accountType, new Date().toISOString(), description, debit, credit, newBalance);

    db.prepare(`UPDATE ${table} SET wallet = ? WHERE id = ?`).run(newBalance, accountId);
    return newBalance;
};

const placeBulkBets = (userId, gameId, betGroups) => {
    let results;
    runInTransaction(() => {
        const user = findAccountById(userId, 'users');
        const game = findAccountById(gameId, 'games');
        const dealer = findAccountById(user.dealerId, 'dealers');
        const admin = findAccountById('Guru', 'admins');

        let totalStake = 0;
        betGroups.forEach(g => totalStake += g.numbers.length * g.amountPerNumber);

        // 1. Deduct full stake from User
        addLedgerEntry(user.id, 'USER', `Stake: ${game.name}`, totalStake, 0);

        // 2. Pay Commissions (Net margin logic)
        const userComm = totalStake * (user.commissionRate / 100);
        const dealerComm = totalStake * ((dealer.commissionRate - user.commissionRate) / 100);

        if (userComm > 0) addLedgerEntry(user.id, 'USER', `Comm: ${game.name}`, 0, userComm);
        if (dealerComm > 0) addLedgerEntry(dealer.id, 'DEALER', `User Bet Margin: ${user.id}`, 0, dealerComm);

        // 3. Admin tracks stake
        addLedgerEntry(admin.id, 'ADMIN', `Stake In: ${user.id} (${game.name})`, 0, totalStake);
        const totalSysComm = userComm + dealerComm;
        if (totalSysComm > 0) addLedgerEntry(admin.id, 'ADMIN', `Comm Out: ${game.name}`, totalSysComm, 0);

        results = betGroups.map(g => {
            const betId = uuidv4();
            db.prepare('INSERT INTO bets (id, userId, dealerId, gameId, subGameType, numbers, amountPerNumber, totalAmount, timestamp) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)')
              .run(betId, userId, dealer.id, gameId, g.subGameType, JSON.stringify(g.numbers), g.amountPerNumber, g.numbers.length * g.amountPerNumber, new Date().toISOString());
            return { id: betId, ...g };
        });
    });
    return results;
};

const topUpUserWallet = (dealerId, userId, amount) => {
    runInTransaction(() => {
        const dealer = findAccountById(dealerId, 'dealers');
        const user = findAccountById(userId, 'users');
        if (dealer.wallet < amount) throw { status: 400, message: 'Dealer insufficient funds.' };

        addLedgerEntry(dealer.id, 'DEALER', `Transfer to ${user.name}`, amount, 0);
        addLedgerEntry(user.id, 'USER', `Deposit from ${dealer.name}`, 0, amount);
    });
};

const withdrawFromUserWallet = (dealerId, userId, amount) => {
    runInTransaction(() => {
        const dealer = findAccountById(dealerId, 'dealers');
        const user = findAccountById(userId, 'users');
        if (user.wallet < amount) throw { status: 400, message: 'User insufficient funds.' };

        addLedgerEntry(user.id, 'USER', `Withdrawal to ${dealer.name}`, amount, 0);
        addLedgerEntry(dealer.id, 'DEALER', `Recovered from ${user.name}`, 0, amount);
    });
};

const declareWinner = (gameId, winningNumber) => {
    db.prepare('UPDATE games SET winningNumber = ? WHERE id = ?').run(winningNumber, gameId);
};

const approvePayouts = (gameId) => {
    runInTransaction(() => {
        const game = findAccountById(gameId, 'games');
        const admin = findAccountById('Guru', 'admins');
        if (!game.winningNumber) throw new Error("No winning number set.");
        if (game.payoutsApproved) throw new Error("Already approved.");

        const bets = db.prepare('SELECT * FROM bets WHERE gameId = ?').all(gameId);

        bets.forEach(bet => {
            const user = findAccountById(bet.userId, 'users');
            const dealer = findAccountById(bet.dealerId, 'dealers');
            const numbers = JSON.parse(bet.numbers);
            const subType = bet.subGameType;

            let winCount = 0;
            numbers.forEach(n => {
                if (subType === '1 Digit Open' && game.winningNumber[0] === n) winCount++;
                else if (subType === '1 Digit Close' && game.winningNumber[1] === n) winCount++;
                else if (subType === '2 Digit' && game.winningNumber === n) winCount++;
                else if (n === game.winningNumber) winCount++; // Default match
            });

            if (winCount > 0) {
                const userRate = subType.includes('1 Digit Open') ? user.prizeRates.oneDigitOpen : (subType.includes('1 Digit Close') ? user.prizeRates.oneDigitClose : user.prizeRates.twoDigit);
                const dealerRate = subType.includes('1 Digit Open') ? dealer.prizeRates.oneDigitOpen : (subType.includes('1 Digit Close') ? dealer.prizeRates.oneDigitClose : dealer.prizeRates.twoDigit);
                const adminRate = subType.includes('1 Digit Open') ? admin.prizeRates.oneDigitOpen : (subType.includes('1 Digit Close') ? admin.prizeRates.oneDigitClose : admin.prizeRates.twoDigit);

                const userPrize = winCount * bet.amountPerNumber * userRate;
                const dealerMarginProfit = winCount * bet.amountPerNumber * (dealerRate - userRate);
                const adminMarginProfit = winCount * bet.amountPerNumber * (adminRate - dealerRate);

                // Admin pays out
                const totalPayoutFromSys = userPrize + dealerMarginProfit;
                addLedgerEntry(admin.id, 'ADMIN', `Prize Payout: ${game.name} to ${user.id}`, totalPayoutFromSys, 0);

                // Credit User
                addLedgerEntry(user.id, 'USER', `Win: ${game.name}`, 0, userPrize);

                // Credit Dealer Margin
                if (dealerMarginProfit > 0) {
                    addLedgerEntry(dealer.id, 'DEALER', `User Win Margin: ${user.id} (${game.name})`, 0, dealerMarginProfit);
                }
            }
        });

        db.prepare('UPDATE games SET payoutsApproved = 1 WHERE id = ?').run(gameId);
    });
};

module.exports = {
    connect, verifySchema, findAccountById, findAccountForLogin,
    getAllFromTable, findUsersByDealerId, findBetsByDealerId,
    runInTransaction, addLedgerEntry, placeBulkBets,
    topUpUserWallet, withdrawFromUserWallet,
    declareWinner, approvePayouts,
    updateUser: (data, id, dealerId) => {
        db.prepare('UPDATE users SET name=?, password=?, area=?, contact=?, commissionRate=?, prizeRates=?, betLimits=?, avatarUrl=? WHERE id=? AND dealerId=?')
          .run(data.name, data.password, data.area, data.contact, data.commissionRate, JSON.stringify(data.prizeRates), JSON.stringify(data.betLimits), data.avatarUrl, id, dealerId);
        return findAccountById(id, 'users');
    },
    updateDealer: (data, id) => {
        db.prepare('UPDATE dealers SET name=?, password=?, area=?, contact=?, commissionRate=?, prizeRates=?, avatarUrl=? WHERE id=?')
          .run(data.name, data.password, data.area, data.contact, data.commissionRate, JSON.stringify(data.prizeRates), data.avatarUrl, id);
        return findAccountById(id, 'dealers');
    },
    toggleAccountRestriction: (id, table) => {
        db.prepare(`UPDATE ${table} SET isRestricted = 1 - isRestricted WHERE id = ?`).run(id);
        return findAccountById(id, table);
    },
    updateDrawTime: (gameId, time) => {
        db.prepare('UPDATE games SET drawTime = ? WHERE id = ?').run(time, gameId);
    },
    createUser: (data, dealerId, deposit) => {
        let newUser;
        runInTransaction(() => {
            db.prepare('INSERT INTO users (id, name, password, dealerId, area, contact, wallet, commissionRate, isRestricted, prizeRates, betLimits, avatarUrl) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
              .run(data.id, data.name, data.password, dealerId, data.area, data.contact, 0, data.commissionRate, 0, JSON.stringify(data.prizeRates), JSON.stringify(data.betLimits), data.avatarUrl);
            if (deposit > 0) {
                const dealer = findAccountById(dealerId, 'dealers');
                addLedgerEntry(dealerId, 'DEALER', `Load ${data.id}`, deposit, 0);
                addLedgerEntry(data.id, 'USER', 'Initial Load', 0, deposit);
            }
            newUser = findAccountById(data.id, 'users');
        });
        return newUser;
    },
    getFinancialSummary: () => {
        const games = db.prepare('SELECT * FROM games').all();
        const admin = findAccountById('Guru', 'admins');
        return {
            games: games.map(g => ({
                gameName: g.name,
                winningNumber: g.winningNumber || '---',
                totalStake: db.prepare('SELECT SUM(totalAmount) as s FROM bets WHERE gameId=?').get(g.id).s || 0,
                totalPayouts: 0, // Simplified
                netProfit: 0
            })),
            totals: { totalStake: 0, netProfit: admin.wallet },
            totalBets: db.prepare('SELECT COUNT(*) as c FROM bets').get().c
        };
    }
};

require('dotenv').config();
const express = require('express');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const authMiddleware = require('./authMiddleware');
const database = require('./database');

const app = express();
app.use(cors());
app.use(express.json());

const JWT_SECRET = process.env.JWT_SECRET || 'fallback_secret';

try {
    database.connect();
    database.verifySchema();
} catch (err) {
    process.exit(1);
}

// --- AUTH ---
app.post('/api/auth/login', (req, res) => {
    const { loginId, password } = req.body;
    const { account, role } = database.findAccountForLogin(loginId);
    if (account && account.password === password) {
        const fullAccount = database.findAccountById(account.id, role.toLowerCase() + 's');
        const token = jwt.sign({ id: account.id, role }, JWT_SECRET, { expiresIn: '1d' });
        return res.json({ token, role, account: fullAccount });
    }
    res.status(401).json({ message: 'Invalid Login ID or Password.' });
});

app.get('/api/auth/verify', authMiddleware, (req, res) => {
    const table = req.user.role.toLowerCase() + 's';
    const account = database.findAccountById(req.user.id, table);
    if (!account) return res.status(404).json({ message: 'Account not found.' });
    res.json({ account, role: req.user.role });
});

// --- COMMON ---
app.get('/api/games', (req, res) => {
    res.json(database.getAllFromTable('games'));
});

// --- USER ---
app.get('/api/user/data', authMiddleware, (req, res) => {
    if (req.user.role !== 'USER') return res.status(403).json({ message: 'Forbidden' });
    const games = database.getAllFromTable('games');
    const bets = database.getAllFromTable('bets').filter(b => b.userId === req.user.id);
    res.json({ games, bets });
});

app.post('/api/user/bets', authMiddleware, (req, res) => {
    if (req.user.role !== 'USER') return res.status(403).json({ message: 'Forbidden' });
    try {
        const result = database.placeBulkBets(req.user.id, req.body.gameId, req.body.betGroups);
        res.json(result);
    } catch (e) {
        res.status(e.status || 500).json({ message: e.message });
    }
});

// --- DEALER ---
app.get('/api/dealer/data', authMiddleware, (req, res) => {
    if (req.user.role !== 'DEALER') return res.status(403).json({ message: 'Forbidden' });
    const users = database.findUsersByDealerId(req.user.id);
    const bets = database.findBetsByDealerId(req.user.id);
    res.json({ users, bets });
});

app.post('/api/dealer/topup/user', authMiddleware, (req, res) => {
    if (req.user.role !== 'DEALER') return res.status(403).json({ message: 'Forbidden' });
    try {
        database.topUpUserWallet(req.user.id, req.body.userId, req.body.amount);
        res.json({ message: 'Top-up success' });
    } catch (e) { res.status(e.status || 500).json({ message: e.message }); }
});

app.post('/api/dealer/withdraw/user', authMiddleware, (req, res) => {
    if (req.user.role !== 'DEALER') return res.status(403).json({ message: 'Forbidden' });
    try {
        database.withdrawFromUserWallet(req.user.id, req.body.userId, req.body.amount);
        res.json({ message: 'Withdraw success' });
