                     { 'wallet' in account && (
                        <div className="hidden md:flex items-center bg-slate-800/50 px-4 py-2 rounded-md border border-slate-700 shadow-inner">
                            {React.cloneElement(Icons.wallet, { className: "h-6 w-6 mr-3 text-cyan-400" })}
                            <span className="font-semibold text-white text-lg tracking-wider">PKR {account.wallet.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                        </div>
                    )}
                    <button onClick={logout} className="bg-slate-700/50 border border-slate-600 hover:bg-red-500/30 hover:border-red-500/50 text-white font-bold py-2 px-4 rounded-md transition-all duration-300">Logout</button>
                </div>
            </div>
        </header>
    );
};

const AppContent: React.FC = () => {
    const { role, account, loading, fetchWithAuth } = useAuth();
    const [users, setUsers] = useState<User[]>([]);
    const [dealers, setDealers] = useState<Dealer[]>([]);
    const [games, setGames] = useState<Game[]>([]);
    const [bets, setBets] = useState<Bet[]>([]);

    // Reveal State
    const [activeReveal, setActiveReveal] = useState<{ name: string; number: string } | null>(null);
    const lastGamesRef = useRef<Game[]>([]);

    const parseAllDates = (data: any) => {
        const parseLedger = (ledger: LedgerEntry[] = []) => ledger.map(e => ({...e, timestamp: new Date(e.timestamp)}));
        if (data.users) data.users = data.users.map((u: User) => ({...u, ledger: parseLedger(u.ledger)}));
        if (data.dealers) data.dealers = data.dealers.map((d: Dealer) => ({...d, ledger: parseLedger(d.ledger)}));
        if (data.bets) data.bets = data.bets.map((b: Bet) => ({...b, timestamp: new Date(b.timestamp)}));
        return data;
    };

    const fetchData = useCallback(async () => {
        if (!role || !account) return;
        try {
            let data;
            if (role === Role.Admin) {
                const response = await fetchWithAuth('/api/admin/data');
                if (!response.ok) throw new Error('Failed to fetch admin data');
                data = await response.json();
                const parsedData = parseAllDates(data);
                setUsers(parsedData.users);
                setDealers(parsedData.dealers);
                setGames(parsedData.games);
                setBets(parsedData.bets);
            } else if (role === Role.Dealer) {
                const response = await fetchWithAuth('/api/dealer/data');
                if (!response.ok) throw new Error('Failed to fetch dealer data');
                data = await response.json();
                const parsedData = parseAllDates(data);
                setUsers(parsedData.users);
                setBets(parsedData.bets);
                const gamesResponse = await fetchWithAuth('/api/games');
                const gamesData = await gamesResponse.json();
                setGames(gamesData);
            } else if (role === Role.User) {
                const response = await fetchWithAuth('/api/user/data');
                if (!response.ok) throw new Error('Failed to fetch user data');
                data = await response.json();
                const parsedData = parseAllDates(data);
                setGames(parsedData.games);
                setBets(parsedData.bets);
            }
        } catch (error) {
            console.error("Failed to fetch data:", error);
        }
    }, [role, account, fetchWithAuth]);

    // Detect new winners for the reveal animation
    useEffect(() => {
        if (games.length > 0 && lastGamesRef.current.length > 0) {
            // Check for new winners in the incoming data
            games.forEach(newGame => {
                const oldGame = lastGamesRef.current.find(g => g.id === newGame.id);
                // Trigger reveal if winningNumber appeared and wasn't there before
                // Also ignore partial AK winners (ending with _)
                if (newGame.winningNumber && 
                    !newGame.winningNumber.endsWith('_') && 
                    (!oldGame || !oldGame.winningNumber || oldGame.winningNumber.endsWith('_'))
                ) {
                    setActiveReveal({ name: newGame.name, number: newGame.winningNumber });
                }
            });
        }
        lastGamesRef.current = games;
    }, [games]);

    useEffect(() => {
        let intervalId: ReturnType<typeof setInterval> | undefined;

        if (account) {
            fetchData(); // Initial fetch on login/account change

            if (role === Role.User || role === Role.Dealer || role === Role.Admin) {
                intervalId = setInterval(fetchData, 1000); // Poll every second
            }
        } else {
            // Clear data on logout
            setUsers([]);
            setDealers([]);
            setGames([]);
            setBets([]);
        }

        return () => {
            if (intervalId) {
                clearInterval(intervalId);
            }
        };
    }, [account, role, fetchData]);

    const placeBet = useCallback(async (details: {
        userId: string;
        gameId: string;
        betGroups: { subGameType: SubGameType; numbers: string[]; amountPerNumber: number }[];
    }): Promise<void> => {
        const response = await fetchWithAuth('/api/user/bets', {
            method: 'POST',
            body: JSON.stringify({
                gameId: details.gameId,
                betGroups: details.betGroups,
            })
        });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const placeBetAsDealer = useCallback(async (details: {
        userId: string;
        gameId: string;
        betGroups: { subGameType: SubGameType; numbers: string[]; amountPerNumber: number }[];
    }) => {
        const response = await fetchWithAuth('/api/dealer/bets/bulk', {
            method: 'POST',
            body: JSON.stringify(details)
        });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const onPlaceAdminBets = useCallback(async (details: {
        userId: string;
        gameId: string;
        betGroups: any[];
    }) => {
        const response = await fetchWithAuth('/api/admin/bulk-bet', {
            method: 'POST',
            body: JSON.stringify(details),
        });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message || 'Failed to place bets.');
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const onSaveUser = useCallback(async (userData: User, originalId: string | undefined, initialDeposit?: number) => {
        let response;
        if (originalId) {
            response = await fetchWithAuth(`/api/dealer/users/${originalId}`, { method: 'PUT', body: JSON.stringify(userData) });
        } else {
            response = await fetchWithAuth('/api/dealer/users', { method: 'POST', body: JSON.stringify({ userData, initialDeposit }) });
        }
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const onSaveDealer = useCallback(async (dealerData: Dealer, originalId?: string) => {
        let response;
        if (originalId) {
            response = await fetchWithAuth(`/api/admin/dealers/${originalId}`, { method: 'PUT', body: JSON.stringify(dealerData) });
        } else {
            response = await fetchWithAuth('/api/admin/dealers', { method: 'POST', body: JSON.stringify(dealerData) });
        }
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const topUpUserWallet = useCallback(async (userId: string, amount: number) => {
        const response = await fetchWithAuth('/api/dealer/topup/user', { method: 'POST', body: JSON.stringify({ userId, amount }) });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const withdrawFromUserWallet = useCallback(async (userId: string, amount: number) => {
        const response = await fetchWithAuth('/api/dealer/withdraw/user', { method: 'POST', body: JSON.stringify({ userId, amount }) });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);


    const declareWinner = useCallback(async (gameId: string, winningNumber: string) => {
        const response = await fetchWithAuth(`/api/admin/games/${gameId}/declare-winner`, { method: 'POST', body: JSON.stringify({ winningNumber }) });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const updateWinner = useCallback(async (gameId: string, newWinningNumber: string) => {
        const response = await fetchWithAuth(`/api/admin/games/${gameId}/update-winner`, { method: 'PUT', body: JSON.stringify({ newWinningNumber }) });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);


    const approvePayouts = useCallback(async (gameId: string) => {
        const response = await fetchWithAuth(`/api/admin/games/${gameId}/approve-payouts`, { method: 'POST' });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const topUpDealerWallet = useCallback(async (dealerId: string, amount: number) => {
        const response = await fetchWithAuth('/api/admin/topup/dealer', { method: 'POST', body: JSON.stringify({ dealerId, amount }) });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    const withdrawFromDealerWallet = useCallback(async (dealerId: string, amount: number) => {
        const response = await fetchWithAuth('/api/admin/withdraw/dealer', { method: 'POST', body: JSON.stringify({ dealerId, amount }) });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);


    const toggleAccountRestriction = useCallback(async (accountId: string, accountType: 'user' | 'dealer') => {
        let url;
        if (role === Role.Admin) {
            url = `/api/admin/accounts/${accountType}/${accountId}/toggle-restriction`;
        } else if (role === Role.Dealer && accountType === 'user') {
            url = `/api/dealer/users/${accountId}/toggle-restriction`;
        } else {
            throw new Error("You don't have permission for this action.");
        }
        const response = await fetchWithAuth(url, { method: 'PUT' });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData, role]);

    const updateGameDrawTime = useCallback(async (gameId: string, newDrawTime: string) => {
        const response = await fetchWithAuth(`/api/admin/games/${gameId}/draw-time`, {
            method: 'PUT',
            body: JSON.stringify({ newDrawTime })
        });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message);
        }
        await fetchData();
    }, [fetchWithAuth, fetchData]);

    if (loading) {
       return <div className="min-h-screen flex items-center justify-center text-cyan-400 text-xl">Loading Session...</div>;
    }

    if (!role || !account) {
        return <LandingPage />;
    }

    return (
        <div className="min-h-screen flex flex-col">
            <Header />
            <main className="flex-grow">
                {role === Role.User && <UserPanel user={account as User} games={games} bets={bets} placeBet={placeBet} />}
                {role === Role.Dealer && <DealerPanel dealer={account as Dealer} users={users} onSaveUser={onSaveUser} topUpUserWallet={topUpUserWallet} withdrawFromUserWallet={withdrawFromUserWallet} toggleAccountRestriction={toggleAccountRestriction} bets={bets} games={games} placeBetAsDealer={placeBetAsDealer} />}
                {role === Role.Admin && <AdminPanel admin={account as Admin} dealers={dealers} onSaveDealer={onSaveDealer} users={users} setUsers={setUsers} games={games} bets={bets} declareWinner={declareWinner} updateWinner={updateWinner} approvePayouts={approvePayouts} topUpDealerWallet={topUpDealerWallet} withdrawFromDealerWallet={withdrawFromDealerWallet} toggleAccountRestriction={toggleAccountRestriction} onPlaceAdminBets={onPlaceAdminBets} updateGameDrawTime={updateGameDrawTime} onRefreshData={fetchData} />}
            </main>

            {/* Global Result Reveal Animation */}
            {activeReveal && (
              <ResultRevealOverlay 
                gameName={activeReveal.name} 
                winningNumber={activeReveal.number} 
                onClose={() => setActiveReveal(null)} 
              />
            )}
        </div>
    );
};

function App() {
  return (
    <div className="App bg-transparent text-slate-200 h-full">
        <AppContent />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';

interface ResultRevealOverlayProps {
  gameName: string;
  winningNumber: string;
  onClose: () => void;
}

const ResultRevealOverlay: React.FC<ResultRevealOverlayProps> = ({ gameName, winningNumber, onClose }) => {
  const [phase, setPhase] = useState<'ROLLING' | 'REVEAL'>('ROLLING');
  const [displayNum, setDisplayNum] = useState('00');

  useEffect(() => {
    // Rolling phase
    // Fix: replaced NodeJS.Timeout with ReturnType<typeof setInterval> for browser environment compatibility
    let interval: ReturnType<typeof setInterval>;
    if (phase === 'ROLLING') {
      interval = setInterval(() => {
        const randomNum = winningNumber.length === 1 
          ? Math.floor(Math.random() * 10).toString()
          : Math.floor(Math.random() * 100).toString().padStart(2, '0');
        setDisplayNum(randomNum);
      }, 50);

      // Duration of roll
      const timer = setTimeout(() => {
        setPhase('REVEAL');
        setDisplayNum(winningNumber);
      }, 3000);

      return () => {
        clearInterval(interval);
        clearTimeout(timer);
      };
    }
  }, [phase, winningNumber]);

  return (
    <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-slate-950/95 backdrop-blur-xl">
      {/* Background Glow */}
      <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/10 via-transparent to-red-500/10 animate-pulse pointer-events-none"></div>

      <div className="relative z-10 text-center px-4">
        <h2 className="text-xl md:text-3xl font-bold text-slate-400 uppercase tracking-[0.3em] mb-2 animate-pulse">
          Official Draw Result
        </h2>
        <h1 className="text-4xl md:text-6xl font-black text-white uppercase tracking-wider mb-12 glitch-text" data-text={gameName}>
          {gameName}
        </h1>

        <div className="relative inline-block">
          {/* Outer Ring */}
          <div className={`w-48 h-48 md:w-64 md:h-64 rounded-full border-8 ${phase === 'REVEAL' ? 'border-emerald-500 shadow-[0_0_50px_rgba(16,185,129,0.5)]' : 'border-cyan-500 shadow-[0_0_30px_rgba(6,182,212,0.3)]'} flex items-center justify-center transition-all duration-500`}>
            <div className={`text-7xl md:text-9xl font-black font-mono tracking-tighter ${phase === 'REVEAL' ? 'text-emerald-400 animate-reveal-slam' : 'text-cyan-400'}`}>
              {displayNum}
            </div>
          </div>

          {/* Decorative Sparks for Reveal */}
          {phase === 'REVEAL' && (
             <div className="absolute -inset-4 border border-emerald-400/30 rounded-full animate-ping"></div>
          )}
        </div>

        <div className="mt-12 h-20">
          {phase === 'REVEAL' ? (
            <div className="space-y-6">
              <p className="text-2xl text-emerald-400 font-bold uppercase tracking-widest animate-bounce">
                Jackpot Winner!
              </p>
              <button 
                onClick={onClose}
                className="bg-white text-slate-900 font-black py-3 px-12 rounded-full hover:bg-emerald-400 hover:text-white transition-all transform hover:scale-110 active:scale-95 shadow-xl"
              >
                CONTINUE
              </button>
            </div>
          ) : (
            <p className="text-lg text-cyan-400/80 font-medium uppercase tracking-[0.5em] animate-pulse">
              Generating...
            </p>
          )}
        </div>
      </div>

      {/* Decorative corners */}
      <div className="absolute top-8 left-8 w-12 h-12 border-t-4 border-l-4 border-cyan-500/50"></div>
      <div className="absolute top-8 right-8 w-12 h-12 border-t-4 border-r-4 border-cyan-500/50"></div>
      <div className="absolute bottom-8 left-8 w-12 h-12 border-b-4 border-l-4 border-cyan-500/50"></div>
      <div className="absolute bottom-8 right-8 w-12 h-12 border-b-4 border-r-4 border-cyan-500/50"></div>
    </div>
  );
};

export default ResultRevealOverlay;

@tailwind base;
@tailwind components;
@tailwind utilities;

html {
  scroll-behavior: smooth;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Russo One', sans-serif;
  background-color: #020617; /* slate-950 */
  touch-action: pan-y; /* Improve mobile scroll */
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.animated-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  z-index: -1;
  background-color: #020617;
  background-image: 
    linear-gradient(rgba(14, 165, 233, 0.1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(14, 165, 233, 0.1) 1px, transparent 1px);
  background-size: 50px 50px;
  animation: pan-grid 60s linear infinite;
}

@keyframes pan-grid {
  0% { background-position: 0 0; }
  100% { background-position: 500px 500px; }
}

/* --- RESULT REVEAL CINEMATICS --- */

@keyframes spotlight-rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes screen-shake {
  0%, 100% { transform: translate(0, 0); }
  10% { transform: translate(-5px, -5px); }
  20% { transform: translate(5px, 5px); }
  30% { transform: translate(-5px, 5px); }
  40% { transform: translate(5px, -5px); }
  50% { transform: translate(-2px, -2px); }
}

@keyframes confetti-fall {
  0% { transform: translateY(-100vh) rotate(0deg); opacity: 1; }
  100% { transform: translateY(100vh) rotate(720deg); opacity: 0; }
}

@keyframes reveal-slam-intense {
  0% { transform: scale(5); opacity: 0; filter: blur(20px); }
  40% { transform: scale(0.8); opacity: 1; filter: blur(0); }
  100% { transform: scale(1); opacity: 1; }
}

@keyframes glow-pulse-gold {
  0%, 100% { box-shadow: 0 0 20px #fbbf24, 0 0 40px #d97706; }
  50% { box-shadow: 0 0 60px #fcd34d, 0 0 100px #fbbf24; }
}

.animate-spotlight {
  animation: spotlight-rotate 10s linear infinite;
}

.animate-reveal-slam-intense {
  animation: reveal-slam-intense 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.animate-shake {
  animation: screen-shake 0.4s ease-in-out;
}

.confetti-piece {
  position: absolute;
  width: 10px;
  height: 10px;
  top: -20px;
  animation: confetti-fall 3s linear infinite;
}

/* Custom Scrollbar */
html::-webkit-scrollbar { width: 8px; }
html::-webkit-scrollbar-track { background: #0f172a; }
html::-webkit-scrollbar-thumb { background-color: #0891b2; border-radius: 20px; border: 2px solid #0f172a; }

.mobile-scroll-x::-webkit-scrollbar {
  height: 6px;
  width: 6px;
}
.mobile-scroll-x::-webkit-scrollbar-track {
  background: transparent;
}
.mobile-scroll-x::-webkit-scrollbar-thumb {
  background-color: rgba(8, 145, 178, 0.5);
  border-radius: 20px;
}

/* Text Glitch Effect */
.glitch-text {
  position: relative;
  color: #67e8f9;
  text-shadow: 0 0 5px #0891b2, 0 0 10px #0891b2;
}
.glitch-text::before,
.glitch-text::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  overflow: hidden;
  clip: rect(0, 900px, 0, 0);
}
.glitch-text::before {
  left: 2px;
  text-shadow: -2px 0 #ec4899;
  animation: glitch-anim-1 2s infinite linear alternate-reverse;
}
.glitch-text::after {
  left: -2px;
  text-shadow: -2px 0 #34d399, 2px 2px #ec4899;
  animation: glitch-anim-2 3s infinite linear alternate-reverse;
}

@keyframes glitch-anim-1 {
  0% { clip: rect(42px, 9999px, 44px, 0); }
  5% { clip: rect(12px, 9999px, 60px, 0); }
  100% { clip: rect(90px, 9999px, 98px, 0); }
}
@keyframes glitch-anim-2 {
  0% { clip: rect(42px, 9999px, 44px, 0); }
  100% { clip: rect(10px, 9999px, 95px, 0); }
}

.animated-check {
  height: 4rem;
  width: 4rem;
}

.animated-check__circle {
  stroke-dasharray: 166;
  stroke-dashoffset: 166;
  stroke-width: 3;
  stroke-miterlimit: 10;
  stroke: #4ade80;
  fill: none;
  animation: stroke 0.6s cubic-bezier(0.65, 0, 0.45, 1) forwards;
}

.animated-check__check {
  transform-origin: 50% 50%;
  stroke-dasharray: 48;
  stroke-dashoffset: 48;
  stroke-width: 4;
  stroke-linecap: round;
  stroke: #4ade80;
  fill: none;
  animation: stroke 0.3s cubic-bezier(0.65, 0, 0.45, 1) 0.8s forwards;
}

@keyframes stroke {
  100% {
    stroke-dashoffset: 0;
  }
}

import React, { useState, useEffect, useMemo } from 'react';

interface ResultRevealOverlayProps {
  gameName: string;
  winningNumber: string;
  onClose: () => void;
}

const Confetti: React.FC = () => {
    const pieces = useMemo(() => {
        return Array.from({ length: 50 }).map((_, i) => ({
            left: Math.random() * 100 + '%',
            delay: Math.random() * 3 + 's',
            color: ['#fbbf24', '#fcd34d', '#f59e0b', '#ffffff', '#94a3b8'][Math.floor(Math.random() * 5)],
            size: Math.random() * 10 + 5 + 'px'
        }));
    }, []);

    return (
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
            {pieces.map((p, i) => (
                <div 
                    key={i} 
                    className="confetti-piece" 
                    style={{ 
                        left: p.left, 
                        animationDelay: p.delay, 
                        backgroundColor: p.color,
                        width: p.size,
                        height: p.size,
                        borderRadius: Math.random() > 0.5 ? '50%' : '2px'
                    }} 
                />
            ))}
        </div>
    );
};

const ResultRevealOverlay: React.FC<ResultRevealOverlayProps> = ({ gameName, winningNumber, onClose }) => {
  const [phase, setPhase] = useState<'ROLLING' | 'REVEAL'>('ROLLING');
  const [displayNum, setDisplayNum] = useState('00');
  const [isShaking, setIsShaking] = useState(false);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (phase === 'ROLLING') {
      interval = setInterval(() => {
        const randomNum = winningNumber.length === 1 
          ? Math.floor(Math.random() * 10).toString()
          : Math.floor(Math.random() * 100).toString().padStart(2, '0');
        setDisplayNum(randomNum);
      }, 40);

      const timer = setTimeout(() => {
        setPhase('REVEAL');
        setDisplayNum(winningNumber);
        setIsShaking(true);
        setTimeout(() => setIsShaking(false), 500);
      }, 3500);

      return () => {
        clearInterval(interval);
        clearTimeout(timer);
      };
    }
  }, [phase, winningNumber]);

  return (
    <div className={`fixed inset-0 z-[100] flex flex-col items-center justify-center bg-slate-950/90 backdrop-blur-2xl transition-all duration-700 ${isShaking ? 'animate-shake' : ''}`}>

