@tailwind base;
@tailwind components;
@tailwind utilities;

html {
  scroll-behavior: smooth;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Russo One', sans-serif;
  background-color: #020617;
  touch-action: pan-y;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.animated-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  z-index: -1;
  background-color: #020617;
  background-image: 
    linear-gradient(rgba(14, 165, 233, 0.1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(14, 165, 233, 0.1) 1px, transparent 1px);
  background-size: 50px 50px;
  animation: pan-grid 60s linear infinite;
}

@keyframes pan-grid {
  0% { background-position: 0 0; }
  100% { background-position: 500px 500px; }
}

/* --- CINEMATIC ANIMATIONS --- */

@keyframes slide-in {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes fade-in {
  from { opacity: 0; transform: translateY(-5px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-slide-in {
  animation: slide-in 0.3s ease-out forwards;
}

.animate-fade-in {
  animation: fade-in 0.2s ease-out forwards;
}

@keyframes spotlight-rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes screen-shake-heavy {
  0%, 100% { transform: translate(0, 0) scale(1); }
  10% { transform: translate(-10px, -10px) scale(1.02); }
  20% { transform: translate(10px, 10px) scale(1.01); }
  30% { transform: translate(-10px, 10px) scale(1.02); }
  40% { transform: translate(10px, -10px) scale(1.01); }
  50% { transform: translate(-5px, -5px) scale(1.02); }
}

@keyframes confetti-fall {
  0% { transform: translateY(-20vh) rotate(0deg) scale(0); opacity: 0; }
  10% { opacity: 1; scale: 1; }
  100% { transform: translateY(110vh) rotate(720deg) scale(0.5); opacity: 0; }
}

@keyframes reveal-slam-hyper {
  0% { transform: scale(8); opacity: 0; filter: blur(40px) brightness(2); }
  40% { transform: scale(0.9); opacity: 1; filter: blur(0) brightness(1.5); }
  100% { transform: scale(1); opacity: 1; filter: brightness(1); }
}

.animate-spotlight {
  animation: spotlight-rotate 10s linear infinite;
}

.animate-reveal-slam-intense {
  animation: reveal-slam-hyper 0.8s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.animate-shake {
  animation: screen-shake-heavy 0.6s ease-in-out;
}

.confetti-piece {
  position: absolute;
  top: -10%;
  animation: confetti-fall 4s ease-in infinite;
}

/* Text Glitch Effect */
.glitch-text {
  position: relative;
  color: #67e8f9;
  text-shadow: 0 0 5px #0891b2, 0 0 10px #0891b2;
}
.glitch-text::before,
.glitch-text::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  overflow: hidden;
  clip: rect(0, 900px, 0, 0);
}
.glitch-text::before {
  left: 2px;
  text-shadow: -2px 0 #ec4899;
  animation: glitch-anim-1 2s infinite linear alternate-reverse;
}
.glitch-text::after {
  left: -2px;
  text-shadow: -2px 0 #34d399, 2px 2px #ec4899;
  animation: glitch-anim-2 3s infinite linear alternate-reverse;
}

@keyframes glitch-anim-1 {
  0% { clip: rect(42px, 9999px, 44px, 0); }
  5% { clip: rect(12px, 9999px, 60px, 0); }
  100% { clip: rect(90px, 9999px, 98px, 0); }
}
@keyframes glitch-anim-2 {
  0% { clip: rect(42px, 9999px, 44px, 0); }
  100% { clip: rect(10px, 9999px, 95px, 0); }
}

