                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                        </>
                                    )}
                                </>
                            ) : (
                                <>
                                    <div className="mb-4">
                                        <div className="flex justify-between items-end mb-1">
                                            <label className="block text-slate-400 text-sm font-medium">Enter Number(s)</label>
