};

const verifySchema = () => {
    try {
        const stmt = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='admins'");
        if (!stmt.get()) {
            console.error('Database schema missing. Run setup-database.js.');
            process.exit(1);
        }
    } catch (error) {
