const AppContent: React.FC = () => {
    const { role, account, loading, fetchWithAuth, verifyData, setAccount } = useAuth();
    const [users, setUsers] = useState<User[]>([]);
    const [dealers, setDealers] = useState<Dealer[]>([]);
    const [games, setGames] = useState<Game[]>([]);
    const [bets, setBets] = useState<Bet[]>([]);
    const [hasInitialFetched, setHasInitialFetched] = useState(false);

    const [activeReveal, setActiveReveal] = useState<{ name: string; number: string } | null>(null);
    const lastGamesRef = useRef<Game[]>([]);

    const parseAllDates = (data: any) => {
        if (!data) return data;
        const parseLedger = (ledger: LedgerEntry[] = []) => ledger.map(e => ({...e, timestamp: new Date(e.timestamp)}));
        if (data.users && Array.isArray(data.users)) data.users = data.users.map((u: User) => u ? ({...u, ledger: parseLedger(u.ledger)}) : null).filter(Boolean);
        if (data.dealers && Array.isArray(data.dealers)) data.dealers = data.dealers.map((d: Dealer) => d ? ({...d, ledger: parseLedger(d.ledger)}) : null).filter(Boolean);
        if (data.bets && Array.isArray(data.bets)) data.bets = data.bets.map((b: Bet) => ({...b, timestamp: new Date(b.timestamp)}));
        if (data.account && data.account.ledger) data.account.ledger = parseLedger(data.account.ledger);
        return data;
    };

    const fetchPublicData = useCallback(async () => {
        try {
            const gamesResponse = await fetch('/api/games');
            if (gamesResponse.ok) setGames(await gamesResponse.json());
        } catch (e) {}
    }, []);

    const fetchPrivateData = useCallback(async () => {
        if (!role) return;
        try {
            const endpoint = role === Role.Admin ? '/api/admin/data' : (role === Role.Dealer ? '/api/dealer/data' : '/api/user/data');
            const response = await fetchWithAuth(endpoint);
            if (response.ok) {
                const parsedData = parseAllDates(await response.json());
                if (parsedData.account) setAccount(parsedData.account);
                if (role === Role.Admin) { setUsers(parsedData.users); setDealers(parsedData.dealers); setBets(parsedData.bets); }
                else if (role === Role.Dealer) { setUsers(parsedData.users); setBets(parsedData.bets); }
                else { setBets(parsedData.bets); }
                setHasInitialFetched(true);
            }
        } catch (error) {
            console.error("Private fetch error", error);
        }
    }, [role, fetchWithAuth, setAccount]);

    useEffect(() => {
        if (!loading && verifyData) {
            const parsed = parseAllDates(verifyData);
            if (parsed.users) setUsers(parsed.users);
            if (parsed.dealers) setDealers(parsed.dealers);
            if (parsed.bets) setBets(parsed.bets);
            setHasInitialFetched(true);
        }
    }, [loading, verifyData]);

    useEffect(() => {
        fetchPublicData();
        const interval = setInterval(fetchPublicData, 5000);
        return () => clearInterval(interval);
    }, [fetchPublicData]);

    useEffect(() => {
        if (role) {
            if (!hasInitialFetched) fetchPrivateData();
            const interval = setInterval(fetchPrivateData, 3000);
            return () => clearInterval(interval);
        } else {
            setHasInitialFetched(false);
            setUsers([]); setBets([]); setDealers([]);
        }
    }, [role, fetchPrivateData]);

    useEffect(() => {
        if (games.length > 0 && lastGamesRef.current.length > 0) {
            games.forEach(newGame => {
                const oldGame = lastGamesRef.current.find(g => g.id === newGame.id);
                if (newGame.winningNumber && !newGame.winningNumber.endsWith('_') && (!oldGame?.winningNumber || oldGame.winningNumber.endsWith('_'))) {
                    setActiveReveal({ name: newGame.name, number: newGame.winningNumber });
                }
            });
        }
        lastGamesRef.current = games;
    }, [games]);

    const placeBet = async (d: any) => { 
        try {
            await fetchWithAuth('/api/user/bets', { method: 'POST', body: JSON.stringify(d) }); 
            fetchPrivateData(); 
        } catch (err: any) { alert(err.message); }
    };

    const placeBetAsDealer = async (d: any) => { 
        try {
            await fetchWithAuth('/api/dealer/bets/bulk', { method: 'POST', body: JSON.stringify(d) }); 
            fetchPrivateData(); 
        } catch (err: any) { alert(err.message); }
    };

    const onSaveUser = async (u: any, o: any, i: any) => {
        const method = o ? 'PUT' : 'POST';
        const url = o ? `/api/dealer/users/${o}` : '/api/dealer/users';
        const response = await fetchWithAuth(url, { method, body: JSON.stringify(o ? u : { userData: u, initialDeposit: i }) });
        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message || 'Operation failed');
        }
        fetchPrivateData();
    };

    const onDeleteUser = async (uId: string) => {
        try {
            const response = await fetchWithAuth(`/api/dealer/users/${uId}`, { method: 'DELETE' });
            if (!response.ok) throw new Error("Failed to delete user");
            fetchPrivateData();
        } catch (err: any) { alert(err.message); }
    };

    if (loading) return <div className="min-h-screen flex items-center justify-center text-cyan-400 text-xl font-bold">Synchronizing Session...</div>;

    return (
        <div className="min-h-screen flex flex-col">
            {!role || !account ? (
                <LandingPage games={games} />
            ) : (
                <>
                    <Header />
                    <main className="flex-grow">
                        {role === Role.User && <UserPanel user={account as User} games={games} bets={bets} placeBet={placeBet} />}
                        {role === Role.Dealer && (
                            <DealerPanel 
                                dealer={account as Dealer} users={users} 
                                onSaveUser={onSaveUser} 
                                onDeleteUser={onDeleteUser}
                                topUpUserWallet={async (id, amt) => { 
                                    try {
                                        await fetchWithAuth('/api/dealer/topup/user', { method: 'POST', body: JSON.stringify({ userId: id, amount: amt }) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); throw err; }
                                }} 
                                withdrawFromUserWallet={async (id, amt) => { 
                                    try {
                                        await fetchWithAuth('/api/dealer/withdraw/user', { method: 'POST', body: JSON.stringify({ userId: id, amount: amt }) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); throw err; }
                                }} 
                                toggleAccountRestriction={async (id) => { 
                                    try {
                                        await fetchWithAuth(`/api/dealer/users/${id}/toggle-restriction`, { method: 'PUT' }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }} 
                                bets={bets} games={games} placeBetAsDealer={placeBetAsDealer} isLoaded={hasInitialFetched}
                            />
                        )}
                        {role === Role.Admin && (
                            <AdminPanel 
                                admin={account as Admin} dealers={dealers} 
                                onSaveDealer={async (d, o) => { 
                                    try {
                                        const url = o ? `/api/admin/dealers/${o}` : '/api/admin/dealers'; 
                                        await fetchWithAuth(url, { method: o ? 'PUT' : 'POST', body: JSON.stringify(d) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }} 
                                onUpdateAdmin={async (a) => { 
                                    try {
                                        await fetchWithAuth('/api/admin/profile', { method: 'PUT', body: JSON.stringify(a) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                users={users} setUsers={setUsers} games={games} bets={bets} 
                                declareWinner={async (id, num) => { 
                                    try {
                                        await fetchWithAuth(`/api/admin/games/${id}/declare-winner`, { method: 'POST', body: JSON.stringify({ winningNumber: num }) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                updateWinner={async (id, num) => { 
                                    try {
                                        await fetchWithAuth(`/api/admin/games/${id}/update-winner`, { method: 'PUT', body: JSON.stringify({ newWinningNumber: num }) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                approvePayouts={async (id) => { 
                                    try {
                                        await fetchWithAuth(`/api/admin/games/${id}/approve-payouts`, { method: 'POST' }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                topUpDealerWallet={async (id, amt) => { 
                                    try {
                                        await fetchWithAuth('/api/admin/topup/dealer', { method: 'POST', body: JSON.stringify({ dealerId: id, amount: amt }) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                withdrawFromDealerWallet={async (id, amt) => { 
                                    try {
                                        await fetchWithAuth('/api/admin/withdraw/dealer', { method: 'POST', body: JSON.stringify({ dealerId: id, amount: amt }) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                toggleAccountRestriction={async (id, type) => { 
                                    try {
                                        await fetchWithAuth(`/api/admin/accounts/${type}/${id}/toggle-restriction`, { method: 'PUT' }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                onPlaceAdminBets={async (d) => { 
                                    try {
                                        await fetchWithAuth('/api/admin/bulk-bet', { method: 'POST', body: JSON.stringify(d) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                updateGameDrawTime={async (id, time) => { 
                                    try {
                                        await fetchWithAuth(`/api/admin/games/${id}/draw-time`, { method: 'PUT', body: JSON.stringify({ newDrawTime: time }) }); 
                                        fetchPrivateData(); 
                                    } catch (err: any) { alert(err.message); }
                                }}
                                onRefreshData={fetchPrivateData} 
                            />
                        )}
                    </main>
                </>
            )}
            {activeReveal && <ResultRevealOverlay gameName={activeReveal.name} winningNumber={activeReveal.number} onClose={() => setActiveReveal(null)} />}
        </div>
    );
};

function App() { return (<div className="App bg-transparent text-slate-200 h-full"><AuthProvider><AppContent /></AuthProvider></div>); }
export default App;

@tailwind base;
@tailwind components;
@tailwind utilities;

html {
  scroll-behavior: smooth;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Russo One', sans-serif;
  background-color: #020617;
  touch-action: pan-y;
  overflow-x: hidden;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Global Button Feedback */
button {
  transition: all 0.1s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
}

button:active:not(:disabled) {
  transform: translateY(1px) scale(0.97);
  filter: brightness(0.9);
}

/* Persistent pressed state for buttons that are processing/disabled */
button:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

/* Buttons specifically marked as 'busy' or 'loading' should look permanently pressed */
button[disabled]:not(.tab-button) {
  filter: brightness(0.8);
  transform: translateY(1px) scale(0.98);
  box-shadow: inset 0 2px 4px rgba(0,0,0,0.3);
}

.animated-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  z-index: -1;
  background-color: #020617;
  background-image: 
    linear-gradient(rgba(14, 165, 233, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(14, 165, 233, 0.05) 1px, transparent 1px);
  background-size: 40px 40px;
  animation: pan-grid 100s linear infinite;
}

@keyframes pan-grid {
  0% { background-position: 0 0; }
  100% { background-position: 1000px 1000px; }
}

@keyframes slide-in {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes fade-in {
  from { opacity: 0; transform: scale(0.95) translateY(-5px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.animate-slide-in {
  animation: slide-in 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.animate-fade-in {
  animation: fade-in 0.2s ease-out forwards;
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}

.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Text Glitch Effect */
.glitch-text {
  position: relative;
  color: #67e8f9;
  text-shadow: 0 0 5px #0891b2;
}
.glitch-text::before,
.glitch-text::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  overflow: hidden;
  clip: rect(0, 900px, 0, 0);
}
.glitch-text::before {
  left: 1px;
  text-shadow: -1px 0 #ec4899;
  animation: glitch-anim-1 3s infinite linear alternate-reverse;
}
.glitch-text::after {
  left: -1px;
  text-shadow: -1px 0 #34d399;
  animation: glitch-anim-2 2s infinite linear alternate-reverse;
}

@keyframes glitch-anim-1 {
  0% { clip: rect(20px, 9999px, 21px, 0); }
  10% { clip: rect(60px, 9999px, 65px, 0); }
  100% { clip: rect(90px, 9999px, 92px, 0); }
}
@keyframes glitch-anim-2 {
  0% { clip: rect(10px, 9999px, 15px, 0); }
  100% { clip: rect(40px, 9999px, 45px, 0); }
}

/* Mobile Scroll Utility */
.mobile-scroll-x {
  -webkit-overflow-scrolling: touch;
}

import React, { useState } from 'react';
import { Game } from '../types';
import { useCountdown } from '../hooks/useCountdown';
import { Icons, GAME_LOGOS } from '../constants';
import { useAuth } from '../hooks/useAuth';

// Helper function to format time to 12-hour AM/PM format
const formatTime12h = (time24: string) => {
    const [hours, minutes] = time24.split(':').map(Number);
    const ampm = hours >= 12 ? 'PM' : 'AM';
    const hours12 = hours % 12 || 12; // Convert 0 to 12
    return `${String(hours12).padStart(2, '0')}:${String(minutes).padStart(2, '0')} ${ampm}`;
};

const GameDisplayCard: React.FC<{ game: Game; onClick: () => void }> = ({ game, onClick }) => {
    const { status, text: countdownText } = useCountdown(game.drawTime);
    // Important: Ignore partial AK results ending in "_" for display
    const hasFinalWinner = !!game.winningNumber && !game.winningNumber.endsWith('_');
    const isMarketClosedForDisplay = !game.isMarketOpen;
    const themeColor = hasFinalWinner ? 'emerald' : 'cyan';
    const logo = GAME_LOGOS[game.name] || '';

    return (
        <button
            onClick={onClick}
            className={`relative group bg-slate-800/50 p-6 flex flex-col items-center justify-between text-center transition-all duration-300 ease-in-out border border-slate-700 w-full overflow-hidden focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 focus:ring-${themeColor}-500 shadow-md hover:shadow-xl`}
            style={{
                clipPath: 'polygon(0 15px, 15px 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%)',
            }}
        >
            {/* Glow effect */}
            <div className={`absolute -inset-0.5 bg-gradient-to-r from-${themeColor}-500 to-blue-500 rounded-lg blur opacity-0 group-hover:opacity-75 transition duration-500`}></div>
            {/* Main content */}
            <div className="relative z-10 w-full flex flex-col h-full">
                <div className="flex-grow">
                    <img src={logo} alt={`${game.name} logo`} className="w-24 h-24 rounded-full mb-4 border-4 border-slate-700 group-hover:border-cyan-400 transition-colors" />
                    <h3 className="text-2xl text-white mb-1 uppercase tracking-wider">{game.name}</h3>
                    <p className="text-slate-400 text-sm">Draw @ {formatTime12h(game.drawTime)}</p>
                </div>
                <div className={`text-center w-full p-2 mt-4 bg-black/30 border-t border-${themeColor}-400/20 min-h-[80px] flex flex-col justify-center`}>
                    {hasFinalWinner ? (
                        <>
                            <div className="text-[10px] uppercase tracking-[0.3em] text-emerald-400 font-black mb-1">DRAW RESULT</div>
                            <div className="text-5xl font-mono font-bold text-white drop-shadow-[0_0_10px_rgba(52,211,153,0.5)] flex items-center justify-center gap-2">
                                <span>{game.winningNumber}</span>
                            </div>
                        </>
                    ) : isMarketClosedForDisplay ? (
                        <>
                            <div className="text-xs uppercase tracking-widest text-slate-400">STATUS</div>
                            <div className="text-2xl font-mono font-bold text-red-400">MARKET CLOSED</div>
                        </>
                    ) : status === 'OPEN' ? (
                        <>
                            <div className="text-xs uppercase tracking-widest text-slate-400">CLOSES IN</div>
                            <div className="text-3xl font-mono font-bold text-cyan-300">{countdownText}</div>
                        </>
                    ) : (
                        <>
                            <div className="text-xs uppercase tracking-widest text-slate-400">MARKET OPENS</div>
                            <div className="text-xl font-mono font-bold text-slate-400">{countdownText}</div>
                        </>
                    )}
                </div>
            </div>
        </button>
    );
};

type LoginRole = 'User' | 'Dealer';

const LoginPanel: React.FC<{ onForgotPassword: () => void }> = ({ onForgotPassword }) => {
    const { login } = useAuth();
    const [activeTab, setActiveTab] = useState<LoginRole>('User');
    const [loginId, setLoginId] = useState('');
    const [password, setPassword] = useState('');
    const [isPasswordVisible, setIsPasswordVisible] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [isAuthenticating, setIsAuthenticating] = useState(false);

    const roles: { name: LoginRole; theme: { text: string; ring: string; button: string; buttonHover: string; } }[] = [
        { name: 'User', theme: { text: 'text-cyan-400', ring: 'focus:ring-cyan-500', button: 'from-cyan-500 to-blue-500', buttonHover: 'hover:from-cyan-400 hover:to-blue-400' } },
        { name: 'Dealer', theme: { text: 'text-emerald-400', ring: 'focus:ring-emerald-500', button: 'from-emerald-500 to-green-500', buttonHover: 'hover:from-emerald-400 hover:to-green-400' } }
    ];

    const activeRole = roles.find(r => r.name === activeTab)!;

    const handleTabClick = (role: LoginRole) => {
        setActiveTab(role);
        setLoginId(''); setPassword(''); setError(null); setIsPasswordVisible(false);
    };

    const handleLoginSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!loginId.trim() || !password.trim()) { setError("Account ID and Password are required."); return; }
        setError(null);
        setIsAuthenticating(true);
        try { 
            await login(loginId, password); 
        } catch (err) { 
            setError(err instanceof Error ? err.message : "An unknown login error occurred."); 
            setIsAuthenticating(false);
        }
    };

    return (
        <div className="bg-slate-800/50 backdrop-blur-sm rounded-lg shadow-2xl border border-slate-700 overflow-hidden">
            <div className="p-1.5 flex items-center space-x-2 bg-black/20">
                {roles.map(role => (
                    <button key={role.name} onClick={() => handleTabClick(role.name)} className={`flex-1 py-2 px-4 text-sm uppercase tracking-widest rounded-md transition-all duration-300 ${activeTab === role.name ? `bg-slate-700 ${activeRole.theme.text} shadow-lg` : 'text-slate-400 hover:bg-slate-700/50 hover:text-white'}`} aria-pressed={activeTab === role.name}>
                        {role.name}
                    </button>
                ))}
            </div>
            <div className="p-8">
                <form onSubmit={handleLoginSubmit} className="space-y-6">
                    <div>
                        <label htmlFor="loginId" className="block text-sm font-medium text-slate-300 mb-1 uppercase tracking-wider">Account ID</label>
                        <input type="text" id="loginId" value={loginId} onChange={(e) => setLoginId(e.target.value)} className={`w-full bg-slate-900/50 p-3 rounded-md border border-slate-600 focus:ring-2 ${activeRole.theme.ring} focus:outline-none text-white placeholder-slate-500 transition-shadow duration-300 shadow-inner`} placeholder={`Enter ${activeTab} ID`} aria-describedby="error-message" />
                    </div>
                    <div>
                         <div className="flex justify-between items-center mb-1">
                            <label htmlFor="password" className="block text-sm font-medium text-slate-300 uppercase tracking-wider">Password</label>
                            <button type="button" onClick={onForgotPassword} className="text-xs text-slate-400 hover:text-cyan-400 transition-colors">Forgot?</button>
                        </div>
                        <div className="relative">
                            <input type={isPasswordVisible ? 'text' : 'password'} id="password" value={password} onChange={(e) => setPassword(e.target.value)} className={`w-full bg-slate-900/50 p-3 rounded-md border border-slate-600 focus:ring-2 ${activeRole.theme.ring} focus:outline-none text-white placeholder-slate-500 transition-shadow duration-300 shadow-inner pr-10`} placeholder="Enter password" aria-describedby="error-message" />
                             <button type="button" onClick={() => setIsPasswordVisible(!isPasswordVisible)} className="absolute inset-y-0 right-0 pr-3 flex items-center text-slate-400 hover:text-white" aria-label={isPasswordVisible ? 'Hide password' : 'Show password'}>
                                {isPasswordVisible ? Icons.eyeOff : Icons.eye}
                            </button>
                        </div>
                    </div>
                    {error && <p id="error-message" role="alert" className="text-sm text-red-300 bg-red-500/20 p-3 rounded-md border border-red-500/30">{error}</p>}
                    <button 
                        type="submit" 
                        disabled={isAuthenticating}
                        className={`w-full text-white font-bold py-3 px-4 rounded-md transition-all duration-300 transform hover:scale-105 active:scale-95 hover:shadow-lg hover:shadow-cyan-500/20 bg-gradient-to-r ${activeRole.theme.button} ${activeRole.theme.buttonHover} flex items-center justify-center gap-2`}
                    >
                        {isAuthenticating ? <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin"></div> : 'LOGIN'}
                    </button>
                </form>
            </div>
        </div>
    );
};

