                            </div>
                            <div className="ml-auto text-right">
                                <div className="text-[9px] text-slate-500 uppercase font-black">Net Profit</div>
                                <div className={`font-mono font-bold ${item.netProfit >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
