function resetAllGames() {
    try {
        runInTransaction(() => {
            db.prepare('UPDATE games SET winningNumber = NULL, payoutsApproved = 0').run();
            db.prepare('DELETE FROM bets').run(); 
        });
        console.error('--- [DATABASE] Daily Reset Triggered. ---');
    } catch (e) {
        logError('DAILY_RESET', e);
    }
}

